declare class TreeNode {
  val: number
  left: TreeNode | null
  right: TreeNode | null
  constructor(val?: number, left?: TreeNode | null, right?: TreeNode | null)
}

function serialize(root: TreeNode | null): string {
  const out: string[] = []
  function walk(n: TreeNode | null) {
    if (!n) {
      out.push('#')
      return
    }
    out.push(String(n.val))
    walk(n.left)
    walk(n.right)
  }
  walk(root)
  return out.join(',')
}

function deserialize(data: string): TreeNode | null {
  const tokens = data.split(',')
  let i = 0
  function build(): TreeNode | null {
    const t = tokens[i++]
    if (t === '#') return null
    const node = new TreeNode(Number(t))
    node.left = build()
    node.right = build()
    return node
  }
  return build()
}
